<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { Delete, Plus, Select } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import ImageUpload from './ImageUpload.vue'

const props=defineProps<{centerKey:string;record:Record<string,any>;activeTab:string;showPrice?:boolean}>()
const emit=defineEmits<{save:[value:any];cancel:[]}>()
const draft=reactive<any>({}),products=ref<any[]>([]),saving=ref(false)
const clone=(value:any)=>JSON.parse(JSON.stringify(value??null))
const row=(values:any={})=>({name:'',description:'',value:'',unit:'',group:'',condition:'',source:'',title:'',image:'',...values})
function reset(){Object.keys(draft).forEach(key=>delete draft[key]);Object.assign(draft,clone(props.record));if(['software','algorithms'].includes(props.centerKey)&&!draft.commercial)draft.commercial={materialCode:'',unit:'套',isAgentProduct:false,agentPrice:null,salePrice:null,warrantyMonths:12,extendedWarrantyRule:'',applicableScenes:[],salesNotes:'',commercialStatus:'ACTIVE',licenseUnit:'',includedQuantity:null,overageUnitPrice:null,deliveryMethod:''};if(props.centerKey==='solutions')loadProducts()}
async function loadProducts(){if(products.value.length)return;const response=await fetch('/api/products',{headers:{Authorization:'Bearer '+localStorage.hzToken}});if(response.ok)products.value=await response.json()}
watch(()=>[props.centerKey,props.record.id],reset,{immediate:true})
const title=computed(()=>({software:'软件','algorithms':'算法','model-capabilities':'模型能力',scenes:'场景',solutions:'方案'} as any)[props.centerKey])
function normalize(list:any[]=[]){return list.map((item,index)=>{const {id,...editable}=item;return {...editable,sortOrder:index}})}
function payload(){
 const base={name:draft.name,code:draft.code||'',version:draft.version||'v1.0',category:draft.category||'通用',status:draft.status,summary:draft.summary||''}
 if(props.centerKey==='software')return {...base,description:draft.description||'',logo:draft.logo||'',softwareType:draft.softwareType||'PLATFORM',vendor:draft.vendor||'',deploymentMode:draft.deploymentMode||'PRIVATE',supportedOs:draft.supportedOs||[],databases:draft.databases||[],protocols:draft.protocols||[],boundaries:draft.boundaries||[],modules:normalize(draft.modules||[]).map((item:any)=>({...item,features:normalize(item.features||[])})),versions:(draft.versions||[]).map((item:any)=>{const {id,...editable}=item;return editable}),screenshots:normalize(draft.screenshots||[])}
 if(props.centerKey==='algorithms')return {...base,principle:draft.principle||'',inputSummary:draft.inputSummary||'',outputSummary:draft.outputSummary||'',parameters:normalize(draft.parameters||[]),metrics:normalize(draft.metrics||[]),boundaries:draft.boundaries||[]}
 if(props.centerKey==='model-capabilities')return {...base,modelType:draft.modelType||'DETECTION',taskType:draft.taskType||'',functionType:draft.functionType||'',metrics:normalize(draft.metrics||[]),inputDefinitions:normalize(draft.inputDefinitions||[]),outputDefinitions:normalize(draft.outputDefinitions||[]),deploymentRequirements:draft.deploymentRequirements||{},useConditions:draft.useConditions||[],boundaries:draft.boundaries||[]}
 if(props.centerKey==='scenes')return {name:draft.name,category:draft.category||'水域安全',summary:draft.summary||'',coverImage:draft.coverImage||'',status:draft.status,tags:draft.tags||[],conditions:draft.conditions||[],painPoints:normalize(draft.painPoints||[]),goals:normalize(draft.goals||[]),process:normalize(draft.process||[]),coreCapabilitySummary:draft.coreCapabilitySummary||''}
 return {...base,sceneId:draft.sceneId,tier:draft.tier||'STANDARD',coverImage:draft.coverImage||'',targetDescription:draft.targetDescription||'',coverageScope:draft.coverageScope||'',implementationNotes:draft.implementationNotes||'',architecture:normalize(draft.architecture||[]),capabilityCoverage:normalize(draft.capabilityCoverage||[])}
}
async function save(){saving.value=true;try{const commercial=draft.commercial?{...draft.commercial,applicableScenes:Array.isArray(draft.commercial.applicableScenes)?draft.commercial.applicableScenes:String(draft.commercial.applicableScenes||'').split(/[、,，\n]/).map((x:string)=>x.trim()).filter(Boolean)}:null;emit('save',{record:payload(),commercial,bom:props.centerKey==='solutions'?{items:(draft.bom?.items||[]).map((item:any)=>({productId:item.productId,quantity:item.quantity,unit:item.unit,purpose:item.purpose,requirementLevel:item.requirementLevel,recommendationReason:item.recommendationReason}))}:null})}finally{saving.value=false}}
function add(target:string,values:any={}){(draft[target]||=[]).push(row(values))}
function addNested(parent:any,target:string,values:any={}){(parent[target]||=[]).push(row(values))}
function pairEntries(value:Record<string,string>={}){return Object.entries(value).map(([key,item])=>({key,value:item}))}
const deploymentRows=computed({get:()=>pairEntries(draft.deploymentRequirements||{}),set:(rows:any[])=>draft.deploymentRequirements=Object.fromEntries(rows.filter(x=>x.key).map(x=>[x.key,x.value]))})
function updateDeployment(rows:any[]){draft.deploymentRequirements=Object.fromEntries(rows.filter(x=>x.key).map(x=>[x.key,x.value]))}
</script>

<template>
  <div class="inline-editor">
    <div class="edit-banner"><span>正在原位编辑{{ title }}，切换页签不会丢失未保存内容</span><div><el-button @click="emit('cancel')">取消</el-button><el-button type="primary" :icon="Select" :loading="saving" @click="save">保存全部修改</el-button></div></div>

    <section v-if="activeTab==='overview'" class="edit-section">
