        <el-form-item label="名称"><el-input v-model="draft.name"/></el-form-item><el-form-item v-if="centerKey!=='scenes'" label="编码"><el-input v-model="draft.code"/></el-form-item>
        <el-form-item v-if="centerKey!=='scenes'" label="版本"><el-input v-model="draft.version"/></el-form-item><el-form-item label="分类"><el-input v-model="draft.category"/></el-form-item>
        <el-form-item label="状态"><el-input v-model="draft.status"/></el-form-item><el-form-item v-if="centerKey==='software'" label="厂商"><el-input v-model="draft.vendor"/></el-form-item>
        <el-form-item v-if="centerKey==='software'" label="软件类型"><el-select v-model="draft.softwareType"><el-option label="平台软件" value="PLATFORM"/><el-option label="客户端软件" value="CLIENT"/><el-option label="服务组件" value="SERVICE"/></el-select></el-form-item>
        <el-form-item v-if="centerKey==='model-capabilities'" label="模型类型"><el-input v-model="draft.modelType"/></el-form-item><el-form-item v-if="centerKey==='model-capabilities'" label="任务类型"><el-input v-model="draft.taskType"/></el-form-item><el-form-item v-if="centerKey==='model-capabilities'" label="功能类型"><el-input v-model="draft.functionType"/></el-form-item>
        <el-form-item v-if="centerKey==='solutions'" label="方案等级"><el-select v-model="draft.tier"><el-option label="标准型" value="STANDARD"/><el-option label="增强型" value="ENHANCED"/><el-option label="旗舰型" value="FLAGSHIP"/></el-select></el-form-item>
        <el-form-item label="简介" class="span-2"><el-input v-model="draft.summary" type="textarea" :rows="3"/></el-form-item><el-form-item v-if="centerKey==='software'" label="详细说明" class="span-2"><el-input v-model="draft.description" type="textarea" :rows="4"/></el-form-item>
      </el-form>
      <ImageUpload v-if="centerKey==='software'" v-model="draft.logo" label="软件 Logo"/><ImageUpload v-if="centerKey==='scenes'" v-model="draft.coverImage" label="场景封面"/><ImageUpload v-if="centerKey==='solutions'" v-model="draft.coverImage" label="方案封面"/>
    </section>

    <section v-else-if="centerKey==='software'" class="edit-section">
      <template v-if="activeTab==='commercial'"><el-form label-position="top" class="form-grid"><el-form-item label="物料代码"><el-input v-model="draft.commercial.materialCode"/></el-form-item><el-form-item label="单位"><el-input v-model="draft.commercial.unit"/></el-form-item><el-form-item label="商业状态"><el-select v-model="draft.commercial.commercialStatus"><el-option label="主推" value="FEATURED"/><el-option label="在售" value="ACTIVE"/><el-option label="库存" value="INVENTORY"/><el-option label="停售" value="DISCONTINUED"/></el-select></el-form-item><el-form-item label="默认质保（月）"><el-input-number v-model="draft.commercial.warrantyMonths" :min="0"/></el-form-item><el-form-item v-if="showPrice" label="代理单价"><el-input-number v-model="draft.commercial.agentPrice" :min="0"/></el-form-item><el-form-item v-if="showPrice" label="销售单价"><el-input-number v-model="draft.commercial.salePrice" :min="0"/></el-form-item><el-form-item label="延保规则" class="span-2"><el-input v-model="draft.commercial.extendedWarrantyRule"/></el-form-item><el-form-item label="适用场景" class="span-2"><el-select v-model="draft.commercial.applicableScenes" multiple allow-create filterable/></el-form-item><el-form-item label="销售备注" class="span-2"><el-input v-model="draft.commercial.salesNotes" type="textarea"/></el-form-item></el-form></template>
      <template v-else-if="activeTab==='functions'"><RepeaterTitle title="系统功能" @add="add('modules',{features:[]})"/><article v-for="(item,index) in draft.modules" :key="index" class="nested-card"><div class="row three"><el-input v-model="item.name" placeholder="模块名称"/><el-input v-model="item.description" placeholder="模块说明"/><el-button :icon="Delete" circle type="danger" plain @click="draft.modules.splice(index,1)"/></div><div v-for="(feature,fi) in item.features" :key="fi" class="row three child"><el-input v-model="feature.name" placeholder="功能名称"/><el-input v-model="feature.description" placeholder="功能说明"/><el-button :icon="Delete" circle plain @click="item.features.splice(fi,1)"/></div><el-button link :icon="Plus" @click="addNested(item,'features')">添加子功能</el-button></article></template>
      <template v-else-if="activeTab==='versions'"><RepeaterTitle title="版本信息" @add="add('versions',{version:'',releasedAt:null,summary:''})"/><div v-for="(item,index) in draft.versions" :key="index" class="row four"><el-input v-model="item.version" placeholder="版本"/><el-date-picker v-model="item.releasedAt" type="date" value-format="YYYY-MM-DD"/><el-input v-model="item.summary" placeholder="更新说明"/><el-button :icon="Delete" circle type="danger" plain @click="draft.versions.splice(index,1)"/></div></template>
      <template v-else-if="activeTab==='deployment'"><div class="form-grid"><el-form-item label="部署方式"><el-select v-model="draft.deploymentMode"><el-option label="私有化部署" value="PRIVATE"/><el-option label="云端部署" value="CLOUD"/><el-option label="混合部署" value="HYBRID"/></el-select></el-form-item><StringList v-model="draft.supportedOs" title="操作系统"/><StringList v-model="draft.databases" title="数据库"/><StringList v-model="draft.protocols" title="支持协议"/></div></template>
      <StringList v-else-if="activeTab==='boundaries'" v-model="draft.boundaries" title="能力边界"/>
      <template v-else-if="activeTab==='screenshots'"><RepeaterTitle title="软件截图" @add="add('screenshots',{image:'',title:''})"/><article v-for="(item,index) in draft.screenshots" :key="index" class="media-row"><ImageUpload v-model="item.image" :label="item.title||'软件截图'"/><el-input v-model="item.title" placeholder="图片说明"/><el-button :icon="Delete" circle type="danger" plain @click="draft.screenshots.splice(index,1)"/></article></template>
    </section>

    <section v-else-if="centerKey==='algorithms'" class="edit-section">
      <el-form v-if="activeTab==='commercial'" label-position="top" class="form-grid"><el-form-item label="物料代码"><el-input v-model="draft.commercial.materialCode"/></el-form-item><el-form-item label="授权单位"><el-input v-model="draft.commercial.licenseUnit"/></el-form-item><el-form-item label="基础路数"><el-input-number v-model="draft.commercial.includedQuantity" :min="0"/></el-form-item><el-form-item label="交付方式"><el-input v-model="draft.commercial.deliveryMethod"/></el-form-item><el-form-item v-if="showPrice" label="代理单价"><el-input-number v-model="draft.commercial.agentPrice" :min="0"/></el-form-item><el-form-item v-if="showPrice" label="销售单价"><el-input-number v-model="draft.commercial.salePrice" :min="0"/></el-form-item><el-form-item v-if="showPrice" label="超额单价"><el-input-number v-model="draft.commercial.overageUnitPrice" :min="0"/></el-form-item><el-form-item label="适用场景" class="span-2"><el-select v-model="draft.commercial.applicableScenes" multiple allow-create filterable/></el-form-item><el-form-item label="销售备注" class="span-2"><el-input v-model="draft.commercial.salesNotes" type="textarea"/></el-form-item></el-form>
      <el-form v-else-if="['principle','input','output'].includes(activeTab)" label-position="top"><el-form-item :label="activeTab==='principle'?'算法原理':activeTab==='input'?'输入数据':'输出结果'"><el-input v-model="draft[activeTab==='principle'?'principle':activeTab==='input'?'inputSummary':'outputSummary']" type="textarea" :rows="8"/></el-form-item></el-form>
      <MetricRows v-else-if="activeTab==='parameters'" v-model="draft.parameters" title="核心参数" :evidence="false"/>
      <MetricRows v-else-if="activeTab==='metrics'" v-model="draft.metrics" title="性能指标" :evidence="true"/>
      <StringList v-else-if="activeTab==='boundaries'" v-model="draft.boundaries" title="能力边界"/>
    </section>

    <section v-else-if="centerKey==='model-capabilities'" class="edit-section">
      <MetricRows v-if="activeTab==='metrics'" v-model="draft.metrics" title="性能指标与测试依据" :evidence="true" :model-evidence="true"/>
      <DefinitionRows v-else-if="activeTab==='input'" v-model="draft.inputDefinitions" title="输入要求" :input="true"/>
      <DefinitionRows v-else-if="activeTab==='output'" v-model="draft.outputDefinitions" title="输出定义"/>
      <template v-else-if="activeTab==='deployment'"><RepeaterTitle title="部署规格" @add="updateDeployment([...deploymentRows,{key:'',value:''}])"/><div v-for="(item,index) in deploymentRows" :key="index" class="row three"><el-input v-model="item.key" placeholder="规格项" @input="updateDeployment(deploymentRows)"/><el-input v-model="item.value" placeholder="要求" @input="updateDeployment(deploymentRows)"/><el-button :icon="Delete" circle type="danger" plain @click="updateDeployment(deploymentRows.filter((_,i)=>i!==index))"/></div><StringList v-model="draft.useConditions" title="使用条件"/></template>
      <StringList v-else-if="activeTab==='boundaries'" v-model="draft.boundaries" title="能力边界"/>
    </section>

    <section v-else-if="centerKey==='scenes'" class="edit-section">
      <ItemRows v-if="activeTab==='pains'" v-model="draft.painPoints" title="业务痛点"/><ItemRows v-else-if="activeTab==='goals'" v-model="draft.goals" title="建设目标"/><StringList v-else-if="activeTab==='conditions'" v-model="draft.conditions" title="关键条件"/>
      <template v-else-if="activeTab==='matrix'"><el-form label-position="top"><el-form-item label="核心能力说明"><el-input v-model="draft.coreCapabilitySummary" type="textarea" :rows="8"/></el-form-item></el-form></template>
      <template v-else-if="activeTab==='process'"><RepeaterTitle title="业务流程" @add="add('process',{nodeTitle:'',nodeDescription:''})"/><div v-for="(item,index) in draft.process" :key="index" class="row three"><el-input v-model="item.nodeTitle" placeholder="节点名称"/><el-input v-model="item.nodeDescription" placeholder="节点说明"/><el-button :icon="Delete" circle type="danger" plain @click="draft.process.splice(index,1)"/></div></template>
    </section>

    <section v-else-if="centerKey==='solutions'" class="edit-section">
      <el-form v-if="activeTab==='conditions'" label-position="top" class="form-grid"><el-form-item label="关联场景"><el-input-number v-model="draft.sceneId" :min="1"/></el-form-item><el-form-item label="适用范围"><el-input v-model="draft.coverageScope"/></el-form-item><el-form-item label="目标说明" class="span-2"><el-input v-model="draft.targetDescription" type="textarea" :rows="5"/></el-form-item><el-form-item label="实施说明" class="span-2"><el-input v-model="draft.implementationNotes" type="textarea" :rows="5"/></el-form-item></el-form>
      <template v-else-if="activeTab==='architecture' || activeTab==='composition'"><RepeaterTitle title="系统架构" @add="add('architecture',{layer:'感知层',relationType:'',relationId:null})"/><div v-for="(item,index) in draft.architecture" :key="index" class="row architecture"><el-input v-model="item.layer" placeholder="层级"/><el-input v-model="item.name" placeholder="组成名称"/><el-input v-model="item.description" placeholder="说明"/><el-button :icon="Delete" circle type="danger" plain @click="draft.architecture.splice(index,1)"/></div></template>
      <template v-else-if="activeTab==='coverage'"><RepeaterTitle title="能力覆盖" @add="add('capabilityCoverage',{capabilityName:'',status:'COVERED',implementation:'',notes:''})"/><div v-for="(item,index) in draft.capabilityCoverage" :key="index" class="row coverage"><el-input v-model="item.capabilityName" placeholder="能力名称"/><el-select v-model="item.status"><el-option label="已覆盖" value="COVERED"/><el-option label="可选" value="OPTIONAL"/><el-option label="未覆盖" value="NOT_COVERED"/></el-select><el-input v-model="item.implementation" placeholder="实现方式"/><el-input v-model="item.notes" placeholder="说明"/><el-button :icon="Delete" circle type="danger" plain @click="draft.capabilityCoverage.splice(index,1)"/></div></template>
      <template v-else-if="activeTab==='bom'"><RepeaterTitle title="标准BOM" @add="(draft.bom.items||=[]).push({productId:products[0]?.id,quantity:1,unit:'台',purpose:'',requirementLevel:'REQUIRED',recommendationReason:''})"/><div v-for="(item,index) in draft.bom.items" :key="index" class="row bom"><el-select v-model="item.productId" filterable><el-option v-for="product in products" :key="product.id" :label="product.name+' · '+product.modelCode" :value="product.id"/></el-select><el-input-number v-model="item.quantity" :min="1"/><el-input v-model="item.unit" placeholder="单位"/><el-input v-model="item.purpose" placeholder="用途"/><el-select v-model="item.requirementLevel"><el-option label="必需" value="REQUIRED"/><el-option label="推荐" value="RECOMMENDED"/><el-option label="可选" value="OPTIONAL"/></el-select><el-input v-model="item.recommendationReason" placeholder="推荐理由"/><el-button :icon="Delete" circle type="danger" plain @click="draft.bom.items.splice(index,1)"/></div></template>
    </section>
  </div>
</template>

<script lang="ts">
import { defineComponent, h } from 'vue'
import { ElButton, ElCheckbox, ElInput, ElSelect, ElOption } from 'element-plus'
export const RepeaterTitle=defineComponent({props:{title:String},emits:['add'],setup(p,{emit}){return()=>h('div',{class:'repeater-title'},[h('div',[h('h2',p.title),h('p','可在当前板块新增、修改和删除。')]),h(ElButton,{icon:Plus,onClick:()=>emit('add')},()=> '新增')])}})
export const StringList=defineComponent({props:{modelValue:{type:Array,default:()=>[]},title:String},emits:['update:modelValue'],setup(p,{emit}){const update=(list:any[])=>emit('update:modelValue',list);return()=>h('div',[h(RepeaterTitle,{title:p.title,onAdd:()=>update([...(p.modelValue as any[]),''])}),...(p.modelValue as any[]).map((item,index)=>h('div',{class:'row two'},[h(ElInput,{modelValue:item,'onUpdate:modelValue':(v:any)=>{const list=[...(p.modelValue as any[])];list[index]=v;update(list)},placeholder:'请输入内容'}),h(ElButton,{icon:Delete,circle:true,type:'danger',plain:true,onClick:()=>update((p.modelValue as any[]).filter((_,i)=>i!==index))})]))])}})
